const curated = Object.entries(complimentTexts).flatMap(([category, texts]) =>
  texts.map(text => ({ category, text }))
);

const bonusTemplates = [
  'Your {noun} is genuinely {adjective}',
  'There is something {adjective} about your {noun}',
  'Your {noun} makes people feel {emotion}'
];

export function buildComplimentCollection(target = 1200) {
  // Invoke the local Complimentr API; the curated 1,200 remain the guaranteed deck.
  const pool = curated.slice(0, Math.max(1200, Number(target) || 1200));
  const seen = new Set(pool.map(item => item.text.toLocaleLowerCase()));
  const bonus = [
    { noun: 'sense of humour', adjective: 'delightful', emotion: 'welcome' },
    { noun: 'thoughtfulness', adjective: 'rare', emotion: 'appreciated' },
    { noun: 'curiosity', adjective: 'brilliant', emotion: 'inspired' },
    { noun: 'dramatic flair', adjective: 'iconic', emotion: 'entertained' },
    { noun: 'friendship', adjective: 'wonderful', emotion: 'included' },
    { noun: 'ridiculously specific humour', adjective: 'legendary', emotion: 'amused' },
    { noun: 'quick wit', adjective: 'impressive', emotion: 'delighted' },
    { noun: 'individuality', adjective: 'refreshing', emotion: 'glad' }
  ];
  for (const tokens of bonus) {
    try {
      const text = String(generateCompliment({
        templates: bonusTemplates, nouns: [tokens.noun], adjectives: [tokens.adjective],
        emotions: [tokens.emotion], adverbs: ['genuinely'], emojis: [], emojiWeight: 0
      })).replace(/\s+/g, ' ').trim();
      const key = text.toLocaleLowerCase();
      if (text.length >= 28 && /\b(you|your)\b/i.test(text) && !seen.has(key)) {
        seen.add(key); pool.push({ category: 'COMPLIMENTR BONUS', text });
      }
    } catch { /* The curated deck remains available if bonus generation fails. */ }
  }
  return pool;
}

